-- Synthetic source database for the utilities demo (Meter-to-cash billed consumption data product)
-- Dialect: db2. Generated by ADEF; all values are synthetic.

CREATE SCHEMA CIS;
CREATE SCHEMA MDM;

-- Customer accounts and status
CREATE TABLE CIS.ACCOUNT (
    ACCOUNT_ID                 VARCHAR(20)        NOT NULL,
    CUSTOMER_NAME              VARCHAR(200)      ,
    SERVICE_ADDRESS            VARCHAR(400)      ,
    ACCOUNT_STATUS             VARCHAR(1)        ,
    RATE_CLASS                 VARCHAR(10)       ,
    OPEN_DATE                  DATE              ,
    CLOSE_DATE                 DATE              ,
    UPDATED_AT                 TIMESTAMP         ,
    LAST_UPDATED_TS            TIMESTAMP         ,
    CONSTRAINT PK_ACCOUNT PRIMARY KEY (ACCOUNT_ID)
);

COMMENT ON COLUMN CIS.ACCOUNT.LAST_UPDATED_TS IS 'Row last changed (CDC watermark)';

-- Service premises
CREATE TABLE CIS.PREMISE (
    PREMISE_ID                 VARCHAR(20)        NOT NULL,
    ACCOUNT_ID                 VARCHAR(20)       ,
    PREMISE_TYPE               VARCHAR(20)       ,
    REGION_CODE                VARCHAR(10)       ,
    POSTAL_CODE                VARCHAR(10)       ,
    LAST_UPDATED_TS            TIMESTAMP         ,
    CONSTRAINT PK_PREMISE PRIMARY KEY (PREMISE_ID)
);

COMMENT ON COLUMN CIS.PREMISE.LAST_UPDATED_TS IS 'Row last changed (CDC watermark)';

-- Installed meters
CREATE TABLE MDM.METER (
    METER_ID                   VARCHAR(20)        NOT NULL,
    PREMISE_ID                 VARCHAR(20)       ,
    METER_TYPE                 VARCHAR(10)       ,
    INSTALL_DATE               DATE              ,
    STATUS                     VARCHAR(10)       ,
    LAST_UPDATED_TS            TIMESTAMP         ,
    CONSTRAINT PK_METER PRIMARY KEY (METER_ID)
);

COMMENT ON COLUMN MDM.METER.LAST_UPDATED_TS IS 'Row last changed (CDC watermark)';

-- Validated daily register reads (high volume)
CREATE TABLE MDM.DAILY_READ (
    METER_ID                   VARCHAR(20)        NOT NULL,
    READ_DATE                  DATE               NOT NULL,
    KWH                        DECIMAL(18,3)     ,
    READ_QUALITY               VARCHAR(1)        ,
    LOADED_AT                  TIMESTAMP         ,
    LAST_UPDATED_TS            TIMESTAMP         ,
    CONSTRAINT PK_DAILY_READ PRIMARY KEY (METER_ID, READ_DATE)
);

COMMENT ON COLUMN MDM.DAILY_READ.KWH IS 'usage linked to a premise';
COMMENT ON COLUMN MDM.DAILY_READ.LAST_UPDATED_TS IS 'Row last changed (CDC watermark)';

-- Issued bills
CREATE TABLE CIS.BILL (
    BILL_ID                    VARCHAR(20)        NOT NULL,
    ACCOUNT_ID                 VARCHAR(20)       ,
    PERIOD_START               DATE              ,
    PERIOD_END                 DATE              ,
    BILLED_KWH                 DECIMAL(18,3)     ,
    AMOUNT_DUE                 DECIMAL(18,2)     ,
    BILL_STATUS                VARCHAR(10)       ,
    LAST_UPDATED_TS            TIMESTAMP         ,
    CONSTRAINT PK_BILL PRIMARY KEY (BILL_ID)
);

COMMENT ON COLUMN CIS.BILL.LAST_UPDATED_TS IS 'Row last changed (CDC watermark)';
